// ─── File: AggregationDemo.java ───
// Models the gateway aggregation pattern: concurrent calls + combine.
// CompletableFuture here mirrors reactive WebClient Monos + Mono.zip (noted inline).
package com.bank.gateway.demo;

import java.util.concurrent.*;
import java.util.logging.*;

public class AggregationDemo {
    private static final Logger log = Logger.getLogger("Aggregation");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new AgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        AccountClient account = new AccountClient();
        CardClient card = new CardClient();
        PaymentClient payment = new PaymentClient();
        DashboardAggregator aggregator = new DashboardAggregator(account, card, payment, pool);

        log.info("=== All services healthy (parallel zip) ===");
        long t1 = System.currentTimeMillis();
        Dashboard d1 = aggregator.aggregate("SAV2001");
        long e1 = System.currentTimeMillis() - t1;
        log.info(() -> "Dashboard = " + d1 + "  (elapsed " + e1 + "ms)");

        log.info("=== Card service DOWN (graceful partial) ===");
        card.setDown(true);
        long t2 = System.currentTimeMillis();
        Dashboard d2 = aggregator.aggregate("SAV2001");
        long e2 = System.currentTimeMillis() - t2;
        log.info(() -> "Dashboard = " + d2 + "  (elapsed " + e2 + "ms)");

        pool.shutdown();
    }
}

