class Dashboard {
    private final String account; private final String card; private final String payments;
    Dashboard(String account, String card, String payments) {
        this.account = account; this.card = card; this.payments = payments;
    }
    @Override public String toString() {
        return "{account=" + account + ", card=" + card + ", payments=" + payments + "}";
    }
}

// ─── Would be in aggregate/DashboardAggregator.java ───
class DashboardAggregator {
    private static final Logger log = Logger.getLogger("Aggregation");
    private final AccountClient account; private final CardClient card; private final PaymentClient payment;
    private final ExecutorService pool;

    DashboardAggregator(AccountClient a, CardClient c, PaymentClient p, ExecutorService pool) {
        this.account = a; this.card = c; this.payment = p; this.pool = pool;
    }

    Dashboard aggregate(String accountId) {
        // Reactive equivalent:
        //   Mono<String> a = webClient.get()...bodyToMono(String.class);
        //   Mono<String> c = webClient.get()...timeout(300ms).onErrorReturn("unavailable");
        //   return Mono.zip(a, c, p).map(t -> new Dashboard(t.getT1(), t.getT2(), t.getT3()));
        // Here we model it with CompletableFuture for a runnable demo.

        CompletableFuture<String> af = CompletableFuture
                .supplyAsync(() -> account.getSummary(accountId), pool);

        CompletableFuture<String> cf = CompletableFuture
                .supplyAsync(() -> card.getStatus(accountId), pool)
                .completeOnTimeout("Card[unavailable]", 300, TimeUnit.MILLISECONDS) // per-call timeout
                .exceptionally(ex -> { log.warning("card fallback: " + ex.getMessage()); return "Card[unavailable]"; });

        CompletableFuture<String> pf = CompletableFuture
                .supplyAsync(() -> payment.getRecent(accountId), pool);

        // zip: wait for all, then combine.
        return CompletableFuture.allOf(af, cf, pf)
                .thenApply(v -> new Dashboard(af.join(), cf.join(), pf.join()))
                .join();
    }
}

// ─── Would be in AgLogFormatter.java ───
class AgLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
